-- Dental Pharmacy content migration (run once after secure-content.sql)
-- 11 notes, 20 practice MCQs and 20 separate mock questions.
on conflict (content_id) do update set
 faculty=excluded.faculty, subject=excluded.subject, content_type=excluded.content_type,
 access_tier=excluded.access_tier, display_order=excluded.display_order,
 content_data=excluded.content_data, is_published=excluded.is_published, updated_at=now();

-- Verify migrated counts
select content_type, access_tier, count(*) as total
from public.learning_content
where subject='Dental Pharmacy' and is_published=true
group by content_type, access_tier
order by content_type, access_tier;
