insert into public.learning_content
(content_id, faculty, subject, content_type, access_tier, display_order, content_data, is_published)
values
('dph-note-01','Dental Hygiene','Dental Pharmacy','note','trial',1,'{"title":"Introduction to dental pharmacy","english":"Dental pharmacy covers medicines used in oral and dental care, their indications, effects, precautions, adverse reactions and safe handling.","nepali":"Dental pharmacy ले मुख तथा दन्त उपचारमा प्रयोग हुने औषधि, प्रयोगका कारण, प्रभाव, सावधानी, प्रतिकूल असर र सुरक्षित व्यवस्थापन समेट्छ।"}'::jsonb,true),
('dph-note-02','Dental Hygiene','Dental Pharmacy','note','trial',2,'{"title":"Basic pharmacology terms","english":"A drug''s indication is the reason for its use; a contraindication is a condition in which it should not be used; an adverse drug reaction is an unwanted harmful response at normal use.","nepali":"Indication भनेको औषधि प्रयोग गर्ने कारण हो; contraindication भनेको प्रयोग गर्न नहुने अवस्था हो; adverse drug reaction भनेको सामान्य प्रयोगमा देखिने अनिच्छित हानिकारक प्रतिक्रिया हो।"}'::jsonb,true),
('dph-note-03','Dental Hygiene','Dental Pharmacy','note','trial',3,'{"title":"Routes of drug administration","english":"Common routes include oral, topical, sublingual, inhalational, intramuscular and intravenous. The route depends on the medicine, clinical need and authorized prescriber’s instructions.","nepali":"औषधि दिने सामान्य मार्ग oral, topical, sublingual, inhalational, intramuscular र intravenous हुन्। कुन मार्ग प्रयोग गर्ने भन्ने कुरा औषधि, क्लिनिकल आवश्यकता र अधिकृत prescriber को निर्देशनमा निर्भर हुन्छ।"}'::jsonb,true),
('dph-note-04','Dental Hygiene','Dental Pharmacy','note','trial',4,'{"title":"Reading a prescription safely","english":"Check the patient, medicine name, strength, dosage form, route, frequency, duration, allergies and prescriber details. Clarify any unclear or incomplete instruction before dispensing or administration.","nepali":"Prescription जाँच्दा बिरामी, औषधिको नाम, strength, dosage form, route, frequency, duration, allergy र prescriber को विवरण हेर्नुपर्छ। अस्पष्ट निर्देशन भए dispensing वा administration अघि स्पष्ट गर्नुपर्छ।"}'::jsonb,true),
('dph-note-05','Dental Hygiene','Dental Pharmacy','note','trial',5,'{"title":"Analgesics in dentistry","english":"Analgesics relieve pain. Paracetamol is commonly used for pain and fever; NSAIDs such as ibuprofen reduce pain and inflammation but may not be suitable for every patient.","nepali":"Analgesics ले दुखाइ कम गर्छन्। Paracetamol दुखाइ र ज्वरोमा प्रयोग हुन्छ; ibuprofen जस्ता NSAIDs ले दुखाइ र inflammation घटाउँछन् तर सबै बिरामीका लागि उपयुक्त हुँदैनन्।"}'::jsonb,true),
('dph-note-06','Dental Hygiene','Dental Pharmacy','note','premium',6,'{"title":"NSAID precautions","english":"NSAIDs may cause gastric irritation or bleeding and can affect kidney function. Caution is needed in patients with peptic ulcer disease, kidney disease, certain cardiovascular conditions, pregnancy and relevant drug interactions.","nepali":"NSAIDs ले पेटमा जलन वा रक्तस्राव गराउन र मिर्गौलाको काममा असर पार्न सक्छन्। Peptic ulcer, kidney disease, केही cardiovascular अवस्था, गर्भावस्था र औषधि interaction भएका बिरामीमा विशेष सावधानी चाहिन्छ।"}'::jsonb,true),
('dph-note-07','Dental Hygiene','Dental Pharmacy','note','premium',7,'{"title":"Antibiotics and antimicrobial stewardship","english":"Antibiotics are indicated for selected bacterial infections, not routine dental pain or viral illness. Use only when clinically indicated and prescribed by an authorized professional; follow the prescribed course and local guidance.","nepali":"Antibiotics केही bacterial infection मा मात्र आवश्यक हुन्छन्; सामान्य दाँत दुखाइ वा viral रोगमा नियमित रूपमा दिनु हुँदैन। क्लिनिकल रूपमा आवश्यक र अधिकृत व्यक्तिले prescribe गरेको अवस्थामा मात्र प्रयोग गरी निर्देशन तथा स्थानीय guideline पालना गर्नुपर्छ।"}'::jsonb,true),
('dph-note-08','Dental Hygiene','Dental Pharmacy','note','premium',8,'{"title":"Common dental antibiotics and allergy","english":"Amoxicillin is a commonly used penicillin antibiotic when indicated. A history of penicillin allergy must be checked and clarified; serious allergy can cause anaphylaxis and needs emergency care.","nepali":"Amoxicillin आवश्यक अवस्थामा प्रयोग हुने सामान्य penicillin antibiotic हो। Penicillin allergy को इतिहास जाँचेर स्पष्ट गर्नुपर्छ; गम्भीर allergy ले anaphylaxis गराउन सक्छ र आपत्कालीन उपचार चाहिन्छ।"}'::jsonb,true),
('dph-note-09','Dental Hygiene','Dental Pharmacy','note','premium',9,'{"title":"Metronidazole and medicine interactions","english":"Metronidazole is active against many anaerobic bacteria and certain protozoa. It has important interactions, including with warfarin; patients should follow current professional advice and product information about alcohol and other precautions.","nepali":"Metronidazole धेरै anaerobic bacteria र केही protozoa विरुद्ध प्रभावकारी हुन्छ। Warfarin लगायतका औषधिसँग interaction हुन सक्छ; alcohol र अन्य सावधानीबारे हालको professional advice तथा औषधिको निर्देशन पालना गर्नुपर्छ।"}'::jsonb,true),
('dph-note-10','Dental Hygiene','Dental Pharmacy','note','premium',10,'{"title":"Local anaesthetics in dentistry","english":"Local anaesthetics temporarily block nerve conduction to prevent pain in a limited area. Check medical history, allergies, dose limits, injection site and signs of toxicity; use only within professional training and authorization.","nepali":"Local anaesthetic ले सीमित क्षेत्रमा nerve conduction अस्थायी रूपमा रोक्दै दुखाइ कम गर्छ। Medical history, allergy, dose limit, injection site र toxicity का लक्षण जाँच्नुपर्छ; आफ्नो तालिम र अधिकारभित्र मात्र प्रयोग गर्नुपर्छ।"}'::jsonb,true),
('dph-note-11','Dental Hygiene','Dental Pharmacy','note','premium',11,'{"title":"Antiseptics, adverse reactions and storage","english":"Chlorhexidine is an oral antiseptic used for selected indications and may cause staining or taste disturbance. Check expiry, storage instructions and packaging; recognize adverse reactions and seek urgent help for breathing difficulty or facial/throat swelling.","nepali":"Chlorhexidine केही अवस्थाहरूमा प्रयोग हुने मुखको antiseptic हो र दाँतमा दाग वा स्वाद परिवर्तन हुन सक्छ। Expiry, storage निर्देशन र packaging जाँच्नुहोस्; प्रतिकूल प्रतिक्रिया पहिचान गर्नुहोस् र सास फेर्न गाह्रो वा अनुहार/घाँटी सुन्निएमा तुरुन्त आपत्कालीन सहायता लिनुहोस्।"}'::jsonb,true),
('dph-mcq-01','Dental Hygiene','Dental Pharmacy','mcq','trial',1,'{"question":"What does the term ''indication'' mean?","translation":"''Indication'' भन्नाले के बुझिन्छ?","options":["A reason for using a medicine","A harmful reaction","The expiry date","A medicine allergy"],"correctIndex":0,"explanation":"An indication is the clinical reason for using a medicine.","explanationNe":"Indication भनेको औषधि प्रयोग गर्ने क्लिनिकल कारण हो।"}'::jsonb,true),
('dph-mcq-02','Dental Hygiene','Dental Pharmacy','mcq','trial',2,'{"question":"A contraindication is:","translation":"Contraindication भनेको के हो?","options":["A reason to increase a dose","A condition in which a medicine should not be used","A brand name","A dosage form"],"correctIndex":1,"explanation":"A contraindication is a situation where a medicine may cause harm or should be avoided.","explanationNe":"औषधि प्रयोग गर्दा हानि हुन सक्ने वा प्रयोग नगर्नुपर्ने अवस्था contraindication हो।"}'::jsonb,true),
('dph-mcq-03','Dental Hygiene','Dental Pharmacy','mcq','trial',3,'{"question":"Which information should be checked before dispensing a prescription?","translation":"Prescription dispense गर्नुअघि कुन जानकारी जाँच्नुपर्छ?","options":["Only the medicine colour","Patient, medicine, strength, directions and allergies","Only the price","Only the manufacturer"],"correctIndex":1,"explanation":"Safe prescription checking includes patient identity, medicine details, instructions and allergy history.","explanationNe":"सुरक्षित जाँचमा बिरामी, औषधि, strength, निर्देशन र allergy इतिहास पर्छ।"}'::jsonb,true),
('dph-mcq-04','Dental Hygiene','Dental Pharmacy','mcq','trial',4,'{"question":"Analgesics are medicines used mainly to:","translation":"Analgesics मुख्यतः केका लागि प्रयोग हुन्छन्?","options":["Relieve pain","Treat all infections","Lower blood glucose","Stop bleeding"],"correctIndex":0,"explanation":"Analgesics are pain-relieving medicines.","explanationNe":"Analgesics दुखाइ कम गर्ने औषधि हुन्।"}'::jsonb,true),
('dph-mcq-05','Dental Hygiene','Dental Pharmacy','mcq','trial',5,'{"question":"Which medicine is commonly used for pain and fever?","translation":"दुखाइ र ज्वरोमा सामान्यतया प्रयोग हुने औषधि कुन हो?","options":["Paracetamol","Amoxicillin","Chlorhexidine","Metronidazole"],"correctIndex":0,"explanation":"Paracetamol is an analgesic and antipyretic.","explanationNe":"Paracetamol दुखाइ कम गर्ने र ज्वरो घटाउने औषधि हो।"}'::jsonb,true),
('dph-mcq-06','Dental Hygiene','Dental Pharmacy','mcq','trial',6,'{"question":"Ibuprofen belongs to which group?","translation":"Ibuprofen कुन औषधि समूहमा पर्छ?","options":["NSAID","Antibiotic","Antiseptic","Local anaesthetic"],"correctIndex":0,"explanation":"Ibuprofen is a non-steroidal anti-inflammatory drug.","explanationNe":"Ibuprofen non-steroidal anti-inflammatory drug (NSAID) हो।"}'::jsonb,true),
('dph-mcq-07','Dental Hygiene','Dental Pharmacy','mcq','trial',7,'{"question":"Which is an important precaution with NSAIDs?","translation":"NSAIDs प्रयोग गर्दा कुन सावधानी महत्त्वपूर्ण छ?","options":["They are safe for every patient","They may increase gastric bleeding risk and affect kidney function","They are antibiotics","They cure viral infections"],"correctIndex":1,"explanation":"NSAIDs can cause gastrointestinal complications and affect renal function in susceptible patients.","explanationNe":"NSAIDs ले पेट/आन्द्रामा रक्तस्रावको जोखिम बढाउन र मिर्गौलामा असर गर्न सक्छन्।"}'::jsonb,true),
('dph-mcq-08','Dental Hygiene','Dental Pharmacy','mcq','trial',8,'{"question":"Antibiotics should generally be used for:","translation":"Antibiotics सामान्यतया कुन अवस्थामा प्रयोग गर्नुपर्छ?","options":["Every toothache","Selected bacterial infections when clinically indicated","All viral infections","Routine prevention for every dental visit"],"correctIndex":1,"explanation":"Antibiotics are not indicated for every dental pain; use depends on diagnosis and clinical need.","explanationNe":"हरेक दाँत दुखाइमा antibiotics चाहिँदैन; diagnosis र क्लिनिकल आवश्यकताअनुसार प्रयोग गरिन्छ।"}'::jsonb,true),
('dph-mcq-09','Dental Hygiene','Dental Pharmacy','mcq','trial',9,'{"question":"Antimicrobial stewardship means:","translation":"Antimicrobial stewardship भन्नाले के बुझिन्छ?","options":["Using antibiotics without diagnosis","Responsible use of antimicrobials to preserve effectiveness","Stopping every prescribed medicine early","Sharing antibiotics with others"],"correctIndex":1,"explanation":"Stewardship promotes appropriate selection and use to reduce resistance and harm.","explanationNe":"Stewardship ले resistance र हानि कम गर्न औषधिको उचित छनोट र प्रयोगलाई प्रोत्साहन गर्छ।"}'::jsonb,true),
('dph-mcq-10','Dental Hygiene','Dental Pharmacy','mcq','trial',10,'{"question":"Amoxicillin belongs to which antibiotic class?","translation":"Amoxicillin कुन antibiotic वर्गमा पर्छ?","options":["Penicillin","Macrolide","Tetracycline","Antifungal"],"correctIndex":0,"explanation":"Amoxicillin is a penicillin-class beta-lactam antibiotic.","explanationNe":"Amoxicillin penicillin वर्गको beta-lactam antibiotic हो।"}'::jsonb,true),
('dph-mcq-11','Dental Hygiene','Dental Pharmacy','mcq','trial',11,'{"question":"A patient reports a history of serious penicillin allergy. What should happen?","translation":"बिरामीले गम्भीर penicillin allergy भएको बतायो भने के गर्नुपर्छ?","options":["Ignore the history","Clarify and document it, and alert the authorized prescriber","Give amoxicillin immediately","Tell the patient allergies are unimportant"],"correctIndex":1,"explanation":"A serious allergy history must be assessed and communicated before a medicine is selected.","explanationNe":"गम्भीर allergy इतिहास औषधि छनोटअघि जाँचेर अधिकृत prescriber लाई जानकारी दिनुपर्छ।"}'::jsonb,true),
('dph-mcq-12','Dental Hygiene','Dental Pharmacy','mcq','trial',12,'{"question":"Anaphylaxis may include:","translation":"Anaphylaxis मा कुन लक्षण देखिन सक्छ?","options":["Breathing difficulty and facial or throat swelling","Mild hunger only","Tooth staining only","Temporary hiccups only"],"correctIndex":0,"explanation":"Anaphylaxis is a life-threatening allergic reaction requiring emergency response.","explanationNe":"Anaphylaxis ज्यान जोखिममा पार्ने allergy प्रतिक्रिया हो र आपत्कालीन सहायता चाहिन्छ।"}'::jsonb,true),
('dph-mcq-13','Dental Hygiene','Dental Pharmacy','mcq','trial',13,'{"question":"Metronidazole is particularly active against many:","translation":"Metronidazole विशेषगरी धेरै कुन जीवाणुविरुद्ध प्रभावकारी हुन्छ?","options":["Anaerobic bacteria","All viruses","Fungi only","Prions"],"correctIndex":0,"explanation":"Metronidazole has activity against many anaerobic bacteria and certain protozoa.","explanationNe":"Metronidazole धेरै anaerobic bacteria र केही protozoa विरुद्ध प्रभावकारी हुन्छ।"}'::jsonb,true),
('dph-mcq-14','Dental Hygiene','Dental Pharmacy','mcq','trial',14,'{"question":"Which medicine may have an important interaction with metronidazole?","translation":"Metronidazole सँग महत्त्वपूर्ण interaction हुन सक्ने औषधि कुन हो?","options":["Warfarin","Normal saline","Topical fluoride varnish","Dental impression material"],"correctIndex":0,"explanation":"Metronidazole can increase the anticoagulant effect of warfarin; professional review is needed.","explanationNe":"Metronidazole ले warfarin को anticoagulant प्रभाव बढाउन सक्छ; professional review आवश्यक हुन्छ।"}'::jsonb,true),
('dph-mcq-15','Dental Hygiene','Dental Pharmacy','mcq','trial',15,'{"question":"Local anaesthetics work mainly by:","translation":"Local anaesthetic ले मुख्यतः कसरी काम गर्छ?","options":["Temporarily blocking nerve conduction","Killing all oral bacteria","Removing dental calculus","Increasing tooth enamel thickness"],"correctIndex":0,"explanation":"Local anaesthetics temporarily block nerve signal conduction in a limited area.","explanationNe":"Local anaesthetic ले सीमित क्षेत्रमा nerve signal अस्थायी रूपमा रोक्छ।"}'::jsonb,true),
('dph-mcq-16','Dental Hygiene','Dental Pharmacy','mcq','trial',16,'{"question":"Before administering a local anaesthetic, one should check:","translation":"Local anaesthetic दिनुअघि के जाँच्नुपर्छ?","options":["Medical history, allergies and relevant dose limits","Only the patient''s shoe size","Only the room temperature","Nothing"],"correctIndex":0,"explanation":"Medical history, allergy status and safe dose limits are essential checks.","explanationNe":"Medical history, allergy र सुरक्षित dose limit जाँच्नु आवश्यक हुन्छ।"}'::jsonb,true),
('dph-mcq-17','Dental Hygiene','Dental Pharmacy','mcq','trial',17,'{"question":"Chlorhexidine is best described as a:","translation":"Chlorhexidine लाई कसरी वर्णन गर्न सकिन्छ?","options":["Oral antiseptic","Systemic antibiotic","Analgesic","Local anaesthetic"],"correctIndex":0,"explanation":"Chlorhexidine is an antiseptic used for selected oral-care indications.","explanationNe":"Chlorhexidine केही मुख स्वास्थ्य अवस्थाहरूमा प्रयोग हुने antiseptic हो।"}'::jsonb,true),
('dph-mcq-18','Dental Hygiene','Dental Pharmacy','mcq','trial',18,'{"question":"A possible side effect of chlorhexidine mouthwash is:","translation":"Chlorhexidine mouthwash को सम्भावित side effect कुन हो?","options":["Tooth staining and taste disturbance","Permanent nerve paralysis","Immediate tooth eruption","Bone fracture"],"correctIndex":0,"explanation":"Chlorhexidine may cause extrinsic staining and altered taste sensation.","explanationNe":"Chlorhexidine ले बाहिरी दाग र स्वाद परिवर्तन गराउन सक्छ।"}'::jsonb,true),
('dph-mcq-19','Dental Hygiene','Dental Pharmacy','mcq','trial',19,'{"question":"What should be checked when storing medicines?","translation":"औषधि भण्डारण गर्दा के जाँच्नुपर्छ?","options":["Expiry date and storage instructions","Only package colour","Only tablet size","Nothing if sealed"],"correctIndex":0,"explanation":"Correct storage and expiry checks help maintain medicine quality and safety.","explanationNe":"सही भण्डारण र expiry जाँचले औषधिको गुणस्तर र सुरक्षा कायम गर्छ।"}'::jsonb,true),
('dph-mcq-20','Dental Hygiene','Dental Pharmacy','mcq','trial',20,'{"question":"Difficulty breathing and throat swelling after a medicine may indicate:","translation":"औषधि खाएपछि सास फेर्न गाह्रो र घाँटी सुन्निनु केको संकेत हुन सक्छ?","options":["A severe allergic reaction requiring emergency help","Normal expected effect","Dental caries","A harmless stain"],"correctIndex":0,"explanation":"Breathing difficulty or throat swelling may signal anaphylaxis; activate emergency care immediately.","explanationNe":"सास फेर्न गाह्रो वा घाँटी सुन्निनु anaphylaxis को संकेत हुन सक्छ; तुरुन्त आपत्कालीन सहायता लिनुपर्छ।"}'::jsonb,true),
('dph-mock-01','Dental Hygiene','Dental Pharmacy','mock','trial',1,'{"question":"Which route of administration places a medicine directly on the oral mucosa?","translation":"कुन route ले औषधि सिधै मुखको mucosa मा लगाउँछ?","options":["Topical","Intravenous","Intramuscular","Inhalational"],"correctIndex":0,"explanation":"Topical administration applies a medicine to a body surface such as oral mucosa.","explanationNe":"Topical route मा औषधि मुखको mucosa जस्तो सतहमा लगाइन्छ।"}'::jsonb,true),
('dph-mock-02','Dental Hygiene','Dental Pharmacy','mock','trial',2,'{"question":"A medicine''s therapeutic effect is its:","translation":"औषधिको therapeutic effect भन्नाले के बुझिन्छ?","options":["Intended beneficial effect","Packaging colour","Expiry date","Taste"],"correctIndex":0,"explanation":"The therapeutic effect is the intended clinical benefit of a medicine.","explanationNe":"Therapeutic effect भनेको औषधिबाट अपेक्षित उपचारात्मक लाभ हो।"}'::jsonb,true),
('dph-mock-03','Dental Hygiene','Dental Pharmacy','mock','trial',3,'{"question":"Which term describes an unwanted effect occurring at a normal medicine dose?","translation":"सामान्य dose मा औषधि प्रयोग गर्दा हुने अनिच्छित असरलाई के भनिन्छ?","options":["Adverse drug reaction","Indication","Therapeutic index","Drug formulation"],"correctIndex":0,"explanation":"An adverse drug reaction is a harmful or unintended response at normally used doses.","explanationNe":"सामान्य dose मा देखिने हानिकारक वा अनिच्छित प्रतिक्रियालाई adverse drug reaction भनिन्छ।"}'::jsonb,true),
('dph-mock-04','Dental Hygiene','Dental Pharmacy','mock','trial',4,'{"question":"Why should a dental professional ask about current medicines?","translation":"दन्त स्वास्थ्यकर्मीले बिरामीले अहिले खाइरहेको औषधिबारे किन सोध्नुपर्छ?","options":["To identify interactions and relevant risks","To recommend stopping all medicines","To replace the medical history","To avoid recording allergies"],"correctIndex":0,"explanation":"Medication history helps identify interactions, contraindications and treatment-related risks.","explanationNe":"औषधिको इतिहासले interaction, contraindication र उपचारसँग सम्बन्धित जोखिम पहिचान गर्न मद्दत गर्छ।"}'::jsonb,true),
('dph-mock-05','Dental Hygiene','Dental Pharmacy','mock','trial',5,'{"question":"Which medicine group reduces fever?","translation":"कुन औषधि समूहले ज्वरो घटाउँछ?","options":["Antipyretics","Antifungals","Antacids","Anticoagulants"],"correctIndex":0,"explanation":"Antipyretics are medicines used to reduce fever.","explanationNe":"Antipyretics ज्वरो घटाउन प्रयोग गरिने औषधि हुन्।"}'::jsonb,true),
('dph-mock-06','Dental Hygiene','Dental Pharmacy','mock','trial',6,'{"question":"A prescription dose is commonly expressed as:","translation":"Prescription मा औषधिको dose सामान्यतया कसरी जनाइन्छ?","options":["A measured amount such as mg","The tablet colour","The pharmacy address","The patient''s occupation"],"correctIndex":0,"explanation":"Dose describes the amount of medicine to be taken or administered, often in units such as mg.","explanationNe":"Dose भनेको लिनुपर्ने वा दिनुपर्ने औषधिको मात्रा हो, जस्तै mg।"}'::jsonb,true),
('dph-mock-07','Dental Hygiene','Dental Pharmacy','mock','trial',7,'{"question":"What is the safest action if a prescription instruction is unclear?","translation":"Prescription को निर्देशन अस्पष्ट भएमा सबैभन्दा सुरक्षित कदम के हो?","options":["Clarify with the prescriber before dispensing","Guess the intended dose","Ask another patient","Dispense without instructions"],"correctIndex":0,"explanation":"Ambiguous prescriptions should be clarified with the authorized prescriber before supply.","explanationNe":"अस्पष्ट prescription औषधि दिनुअघि अधिकृत prescriber सँग स्पष्ट गर्नुपर्छ।"}'::jsonb,true),
('dph-mock-08','Dental Hygiene','Dental Pharmacy','mock','trial',8,'{"question":"Why must medicine expiry dates be checked?","translation":"औषधिको expiry date किन जाँच्नुपर्छ?","options":["To avoid supplying medicines beyond their labelled shelf life","To identify the patient''s diagnosis","To calculate pulse rate","To select a tooth number"],"correctIndex":0,"explanation":"Expired medicines may not meet expected quality, safety or effectiveness standards.","explanationNe":"Expiry नाघेका औषधिको गुणस्तर, सुरक्षा वा प्रभावकारिता सुनिश्चित हुँदैन।"}'::jsonb,true),
('dph-mock-09','Dental Hygiene','Dental Pharmacy','mock','trial',9,'{"question":"Which storage condition is appropriate for many medicines unless the label says otherwise?","translation":"Label मा फरक निर्देशन नभए धेरै औषधिका लागि कुन भण्डारण उपयुक्त हुन्छ?","options":["A cool, dry place away from direct sunlight","A hot vehicle dashboard","A damp sink area","Direct sunlight"],"correctIndex":0,"explanation":"Many medicines require storage away from excess heat, moisture and light; always follow the product label.","explanationNe":"धेरै औषधिलाई अत्यधिक ताप, चिस्यान र प्रकाशबाट टाढा राख्नुपर्छ; सधैँ label पालना गर्नुपर्छ।"}'::jsonb,true),
('dph-mock-10','Dental Hygiene','Dental Pharmacy','mock','trial',10,'{"question":"What should be done with a medicine showing damaged packaging or altered appearance?","translation":"प्याकेट बिग्रिएको वा औषधिको रूप परिवर्तन भएको देखिएमा के गर्नुपर्छ?","options":["Quarantine it and seek pharmacist or supplier guidance","Dispense it quickly","Mix it with another batch","Ignore the change"],"correctIndex":0,"explanation":"Do not use or dispense a medicine when its integrity is in doubt; obtain professional guidance.","explanationNe":"औषधिको गुणस्तरमा शंका भए प्रयोग वा वितरण नगरी सम्बन्धित pharmacy professional/supplier सँग सल्लाह लिनुपर्छ।"}'::jsonb,true),
('dph-mock-11','Dental Hygiene','Dental Pharmacy','mock','trial',11,'{"question":"Which information is essential when documenting a suspected medicine allergy?","translation":"औषधिको शंकास्पद allergy लेख्दा कुन जानकारी महत्त्वपूर्ण हुन्छ?","options":["Suspected medicine and reaction details","Only the patient''s height","Only the medicine price","The clinic opening time"],"correctIndex":0,"explanation":"Record the suspected drug, reaction, timing and severity when known, and communicate it to the care team.","explanationNe":"सम्भव भएसम्म औषधि, प्रतिक्रिया, समय र गम्भीरता अभिलेख गरी उपचार टोलीलाई जानकारी दिनुपर्छ।"}'::jsonb,true),
('dph-mock-12','Dental Hygiene','Dental Pharmacy','mock','trial',12,'{"question":"Which statement about antibiotics and viral infections is correct?","translation":"Antibiotics र viral infection बारे कुन भनाइ सही हो?","options":["Antibiotics do not treat viruses","Antibiotics treat every viral infection","Antibiotics are painkillers","Antibiotics prevent all allergies"],"correctIndex":0,"explanation":"Antibiotics act against susceptible bacteria, not viruses.","explanationNe":"Antibiotics संवेदनशील bacteria विरुद्ध काम गर्छन्, virus विरुद्ध होइनन्।"}'::jsonb,true),
('dph-mock-13','Dental Hygiene','Dental Pharmacy','mock','trial',13,'{"question":"What is the main purpose of a medicine label?","translation":"औषधिको label को मुख्य उद्देश्य के हो?","options":["To communicate identity, strength, directions and safety information","To advertise only the manufacturer","To replace patient counselling","To show the patient''s blood group"],"correctIndex":0,"explanation":"A clear label communicates the medicine and key instructions needed for safe use.","explanationNe":"स्पष्ट label ले औषधिको पहिचान र सुरक्षित प्रयोगका मुख्य निर्देशन दिन्छ।"}'::jsonb,true),
('dph-mock-14','Dental Hygiene','Dental Pharmacy','mock','trial',14,'{"question":"Which action supports safe medicine administration?","translation":"औषधि सुरक्षित रूपमा दिन कुन कामले सहयोग गर्छ?","options":["Confirm the correct patient, medicine, dose, route and time","Rely on memory alone","Use an unlabelled container","Skip allergy checks"],"correctIndex":0,"explanation":"Checking patient, medicine, dose, route and timing reduces preventable medication errors.","explanationNe":"बिरामी, औषधि, dose, route र समय जाँच्दा रोक्न सकिने medication error कम हुन्छ।"}'::jsonb,true),
('dph-mock-15','Dental Hygiene','Dental Pharmacy','mock','trial',15,'{"question":"A topical oral gel should generally be used:","translation":"मुखमा लगाउने topical gel सामान्यतया कसरी प्रयोग गर्नुपर्छ?","options":["According to its product instructions and clinician advice","By swallowing the whole tube","At any amount without checking","Only after changing its label"],"correctIndex":0,"explanation":"Use topical oral medicines exactly as labelled or directed by the treating professional.","explanationNe":"मुखमा लगाउने औषधि label वा उपचार गर्ने स्वास्थ्यकर्मीको निर्देशनअनुसार मात्र प्रयोग गर्नुपर्छ।"}'::jsonb,true),
('dph-mock-16','Dental Hygiene','Dental Pharmacy','mock','trial',16,'{"question":"What is pharmacokinetics concerned with?","translation":"Pharmacokinetics ले के अध्ययन गर्छ?","options":["How the body absorbs, distributes, metabolizes and eliminates a drug","How a drug is marketed","The colour of a tablet","How prescriptions are printed"],"correctIndex":0,"explanation":"Pharmacokinetics describes absorption, distribution, metabolism and excretion (ADME).","explanationNe":"Pharmacokinetics ले औषधिको absorption, distribution, metabolism र excretion (ADME) अध्ययन गर्छ।"}'::jsonb,true),
('dph-mock-17','Dental Hygiene','Dental Pharmacy','mock','trial',17,'{"question":"What does pharmacodynamics describe?","translation":"Pharmacodynamics ले के वर्णन गर्छ?","options":["What a medicine does to the body and its mechanisms of action","How medicines are packaged","How a pharmacy is licensed","How tablets are counted"],"correctIndex":0,"explanation":"Pharmacodynamics concerns drug effects and mechanisms of action in the body.","explanationNe":"Pharmacodynamics ले शरीरमा औषधिको प्रभाव र काम गर्ने तरिका अध्ययन गर्छ।"}'::jsonb,true),
('dph-mock-18','Dental Hygiene','Dental Pharmacy','mock','trial',18,'{"question":"Which patient factor may require additional caution when medicines are selected?","translation":"औषधि छनोट गर्दा कुन बिरामीसम्बन्धी अवस्थाले थप सावधानी आवश्यक पार्न सक्छ?","options":["Pregnancy or breastfeeding","Favourite colour","Shoe size","Preferred music"],"correctIndex":0,"explanation":"Pregnancy and breastfeeding can affect medicine risk-benefit decisions; obtain appropriate clinical advice.","explanationNe":"गर्भावस्था र स्तनपानले औषधिको जोखिम–लाभमा असर पार्न सक्छ; उपयुक्त चिकित्सकीय सल्लाह लिनुपर्छ।"}'::jsonb,true),
('dph-mock-19','Dental Hygiene','Dental Pharmacy','mock','trial',19,'{"question":"What is the correct response to a suspected serious adverse drug reaction?","translation":"गम्भीर adverse drug reaction को शंका भएमा सही कदम के हो?","options":["Arrange urgent clinical assessment and follow local reporting procedures","Tell the patient to ignore it","Continue without assessment","Delete the medicine record"],"correctIndex":0,"explanation":"Serious suspected reactions require prompt clinical assessment and appropriate documentation/reporting.","explanationNe":"गम्भीर प्रतिक्रियामा तुरुन्त क्लिनिकल मूल्याङ्कन र उचित अभिलेख/रिपोर्टिङ आवश्यक हुन्छ।"}'::jsonb,true),
('dph-mock-20','Dental Hygiene','Dental Pharmacy','mock','trial',20,'{"question":"Why should medicines never be shared between patients?","translation":"बिरामीहरूबीच औषधि किन साटासाट गर्नु हुँदैन?","options":["The medicine may be unsuitable or unsafe for another person''s condition","All patients need identical doses","Sharing improves expiry dates","It removes the need for prescriptions"],"correctIndex":0,"explanation":"Medicine choice and dose depend on individual diagnosis, history, allergies and other factors.","explanationNe":"औषधि र dose व्यक्तिको diagnosis, इतिहास, allergy र अन्य अवस्थाअनुसार फरक हुन्छ।"}'::jsonb,true)
